function o(r,e=1){const t=Math.floor(Number(r));return Number.isFinite(t)&&t>0?t:e}function c(r){const e=String(r??"").replace(/\D/g,"");if(!e)return 0;const t=Number(e);return Number.isFinite(t)&&t>0?t:0}function g(r,e){const t=o(e),a=String(t).length,n=r.reduce((i,u)=>{const s=String(u??"").replace(/\D/g,"");return!s||s.length>a?i:Math.max(i,c(s))},0);return Math.max(t,n+1)}function m(r,e){const t=o(e),a=r.reduce((n,i)=>{const u=String(i??"").trim();return/^\d+$/.test(u)?Math.max(n,Number(u)):n},0);return Math.max(t,a+1)}function N(r){return String(Math.max(1,Math.floor(Number(r)||1))).padStart(5,"0")}export{g as a,N as f,m as g};
